import{_ as t,o,c as a,a4 as n}from"./chunks/framework.BE47AOxC.js";const f=JSON.parse('{"title":"ADR-0008 — Authentification du back-office : session opaque révocable plutôt que JWT","description":"Extrait de docs/adr/0008-session-opaque-revocable-back-office.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0008 — Authentification du back-office : session opaque révocable plutôt que JWT","description":"Extrait de docs/adr/0008-session-opaque-revocable-back-office.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0008-session-opaque-revocable-back-office.md","filePath":"developpeurs/adr/0008-session-opaque-revocable-back-office.md"}'),i={name:"developpeurs/adr/0008-session-opaque-revocable-back-office.md"};function s(r,e,c,u,d,l){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0008--authentification-du-back-office--session-opaque-révocable-plutôt-que-jwt" tabindex="-1">ADR-0008 — Authentification du back-office : session opaque révocable plutôt que JWT <a class="header-anchor" href="#adr-0008--authentification-du-back-office--session-opaque-révocable-plutôt-que-jwt" aria-label="Permalink to &quot;ADR-0008 — Authentification du back-office : session opaque révocable plutôt que JWT {#adr-0008--authentification-du-back-office--session-opaque-révocable-plutôt-que-jwt}&quot;">​</a></h1><p><strong>Date :</strong> 19 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §8.1 (login CMS, MFA, SSO/SAML), §13.1 (journal d&#39;accès), §14.11 (le Core démarre sans configuration) ; Epic E6</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;Epic E6 introduit la première authentification réelle du Core. Jusque-là, l&#39;acteur journalisé (<code>app/rgpd/actor.py</code>, Epic E5) était lu dans un en-tête <code>X-Actor-Login</code> — un porteur d&#39;identité <em>déclarée</em>, assumé comme tel faute d&#39;identité à prouver.</p><p>Deux familles de solutions se présentaient pour porter une session de back-office : un <strong>jeton signé auto-porteur</strong> (JWT), ou un <strong>jeton opaque adossé à une table</strong>. Le choix engage le schéma, le format d&#39;API et la configuration de déploiement ; il est coûteux à revenir une fois que des clients l&#39;ont intégré.</p><h2 id="analyse" tabindex="-1">Analyse <a class="header-anchor" href="#analyse" aria-label="Permalink to &quot;Analyse {#analyse}&quot;">​</a></h2><p>Trois exigences du corpus tranchent la question.</p><ol><li><p><strong>La déconnexion doit être effective</strong> (CDC §8.1). Un jeton signé reste valable jusqu&#39;à son échéance quoi qu&#39;il arrive ensuite. Le rendre révocable suppose une liste de révocation consultée à chaque requête, c&#39;est-à-dire la même table qu&#39;une session, avec la complexité en plus et la révocation immédiate en moins.</p></li><li><p><strong>Un droit retiré doit cesser de produire ses effets.</strong> Le RBAC est la raison d&#39;être de cet Epic : un rôle rétrogradé, un compte désactivé, une session de substitution d&#39;identité qui tourne mal doivent prendre effet à l&#39;instant, pas à l&#39;expiration d&#39;un jeton de douze heures. Avec une session en base, le compte et son état sont relus à chaque requête.</p></li><li><p><strong>Le Core doit démarrer sans configuration</strong> (CDC §14.11, principe déjà appliqué au profil IA et au reste du dépôt). Un JWT exige un secret de signature : soit on le rend obligatoire — et <code>docker compose up</code> ne fonctionne plus sans configuration —, soit on livre un secret de développement par défaut, qui finira en production. Un jeton aléatoire opaque n&#39;a besoin d&#39;aucun secret partagé.</p></li></ol><p>L&#39;argument habituel en faveur du JWT — vérifier une session sans accès à la base — ne s&#39;applique pas ici : chaque requête authentifiée du back-office lit de toute façon la base, et l&#39;identité doit être confrontée à l&#39;état courant du compte.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p>Les sessions du back-office sont des <strong>jetons opaques</strong> de 256 bits, tirés de <code>secrets</code>, transmis dans <code>Authorization: Bearer</code>, et adossés à la table <code>staff_sessions</code>. <strong>Seule l&#39;empreinte SHA-256 du jeton est stockée</strong> : une fuite de la table ne rejoue aucune session. La révocation est un horodatage (<code>revoked_at</code>), pas une suppression de ligne.</p><p>Aucun secret de signature n&#39;est introduit dans la configuration du projet.</p><p>Le transport reste le <code>Bearer</code> et <strong>pas un cookie</strong> : un cookie de session implique une protection CSRF, qui n&#39;a de sens qu&#39;articulée avec l&#39;application d&#39;administration qui la consomme. Livrer le cookie sans la protection aurait été le pire des deux.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>JWT signé (HS256/RS256)</strong></td><td>Ne se révoque pas ; exige un secret de signature donc une configuration obligatoire (contre CDC §14.11) ; nécessiterait de toute façon une liste de révocation pour honorer §8.1.</td></tr><tr><td><strong>JWT court + jeton de rafraîchissement</strong></td><td>Ramène la table de sessions par la porte du rafraîchissement, en laissant subsister une fenêtre pendant laquelle un droit retiré agit encore.</td></tr><tr><td><strong>Cookie de session <code>HttpOnly</code> posé par le Core</strong></td><td>Impose une politique CSRF au Core alors que le choix du client (SPA Nuxt, passerelle, application tierce) ne lui appartient pas.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Déconnexion, changement de rôle et désactivation de compte prennent effet immédiatement ; le RBAC est vrai à la requête près.</li><li>Aucune dépendance de chiffrement ni de JWT ajoutée au projet (le hachage de mot de passe utilise <code>hashlib.scrypt</code>, le TOTP <code>hmac</code>) — l&#39;image <code>python:3.12-alpine</code> du dépôt n&#39;a pas besoin de chaîne de compilation.</li><li>Aucun secret de développement à faire traîner dans <code>.env.example</code>.</li></ul><p><strong>Négatives</strong></p><ul><li>Une lecture en base par requête authentifiée. Acceptable : les routes concernées lisent déjà la base, et l&#39;index sur l&#39;empreinte rend la lecture ponctuelle.</li><li>Une authentification sans état, si elle devenait nécessaire pour des services entre eux (Epic E7 ou une architecture distribuée), demandera un mécanisme distinct — qui ne devra pas être confondu avec la session humaine du back-office.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] <code>staff_sessions</code> posée par la migration <code>0007</code>.</li><li>[x] Limitation de débit sur <code>POST /auth/login</code> : le verrouillage par compteur d&#39;échecs est en place, la limitation par origine relève de la passerelle du déploiement (à documenter au jalon de mise en production). → <strong>Close</strong> par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0031-limitation-de-debit">ADR-0031</a> (17/09/2026).</li></ul>',22)])])}const h=t(i,[["render",s]]);export{f as __pageData,h as default};
